// Package dataset holds the region tables embedded in the compiled binary.
//
// The blobs are generated by "go run ./internal/gen" from the CSV export
// published by aliziodev/laravel-wilayah. They are internal on purpose: the
// binary format carries no compatibility promise, only the wilayah API does.
package dataset

import _ "embed"

//go:embed provinces.bin
var Provinces []byte

//go:embed regencies.bin
var Regencies []byte

//go:embed districts.bin
var Districts []byte

//go:embed villages.bin
var Villages []byte

// Metadata is the province and regency attribute table: gzipped CSV rather
// than the packed format, because 552 rows do not justify a binary layout
// that would have to carry numbers.
//
//go:embed metadata.csv.gz
var Metadata []byte
